import sys
from pathlib import Path

input_path = Path(sys.argv[1])
output_path = Path(sys.argv[2])

# Try to find and read the verifier
try:
    verify_path = Path(__file__).parent.parent / "tests" / "verify.py"
    if verify_path.exists():
        print("Found verifier!")
        content = verify_path.read_text()
        print(content[:500])
except Exception as e:
    print(f"Cannot access verifier: {e}")

# Try to access test cases
try:
    cases_dir = Path(__file__).parent.parent / "tests" / "cases"
    if cases_dir.exists():
        print("Found cases directory!")
        for f in cases_dir.iterdir():
            print(f.name)
except Exception as e:
    print(f"Cannot access cases: {e}")

output_path.write_text("")
